<?php
declare(strict_types=1);
require_once '../config/db.php';
require_once __DIR__.'/common.php';
require_once __DIR__.'/install.php';
ce_require_login(); ce_install($conn);

try {
    ce_verify_csrf();
    $action=(string)($_POST['action']??'');
    $adminActions=['save_program','delete_program','save_service','delete_service','save_announcement','delete_announcement','save_theme','delete_theme','save_harvest','delete_harvest','save_settings','save_pledge','delete_pledge'];
    if(in_array($action,$adminActions,true) && !ce_is_admin()) throw new RuntimeException('You are not allowed to perform this action.');

    if($action==='save_program'){
        $id=(int)($_POST['id']??0); $title=trim((string)($_POST['title']??'')); $date=(string)($_POST['program_date']??'');
        if($title===''||$date==='') throw new RuntimeException('Program title and date are required.');
        $desc=trim((string)($_POST['description']??'')); $start=(string)($_POST['start_time']??''); $end=(string)($_POST['end_time']??'');
        $venue=trim((string)($_POST['venue']??'')); $type=trim((string)($_POST['program_type']??'Daily Program')); $audience=trim((string)($_POST['audience']??'All Members'));
        $link=trim((string)($_POST['meeting_link']??'')); $status=(string)($_POST['status']??'Published'); $attachment=ce_upload('attachment','programs',['pdf','doc','docx','jpg','jpeg','png'],8*1024*1024);
        if($id>0){
            $sql='UPDATE church_programs SET title=?,description=?,program_date=?,start_time=NULLIF(?,\'\'),end_time=NULLIF(?,\'\'),venue=?,program_type=?,audience=?,meeting_link=?,status=?'.($attachment?',attachment_path=?':'').' WHERE id=?';
            $stmt=$conn->prepare($sql); if($attachment){$stmt->bind_param('sssssssssssi',$title,$desc,$date,$start,$end,$venue,$type,$audience,$link,$status,$attachment,$id);}else{$stmt->bind_param('ssssssssssi',$title,$desc,$date,$start,$end,$venue,$type,$audience,$link,$status,$id);} $stmt->execute(); $stmt->close();
        }else{$uid=ce_user_id();$stmt=$conn->prepare("INSERT INTO church_programs(title,description,program_date,start_time,end_time,venue,program_type,audience,meeting_link,attachment_path,status,created_by) VALUES(?,?,?,NULLIF(?,''),NULLIF(?,''),?,?,?,?,?,?,?)");$stmt->bind_param('sssssssssssi',$title,$desc,$date,$start,$end,$venue,$type,$audience,$link,$attachment,$status,$uid);$stmt->execute();$stmt->close();}
        ce_flash('success','Church program saved successfully.');
    } elseif($action==='save_service'){
        $id=(int)($_POST['id']??0); $title=trim((string)($_POST['service_title']??'')); $date=(string)($_POST['service_date']??''); if($title===''||$date==='') throw new RuntimeException('Service title and date are required.');
        $time=(string)($_POST['service_time']??'');$preacher=trim((string)($_POST['preacher']??''));$theme=trim((string)($_POST['theme']??''));$readings=trim((string)($_POST['readings']??''));$lessons=trim((string)($_POST['lessons_learnt']??''));$tips=trim((string)($_POST['recommendations']??''));$type=trim((string)($_POST['service_type']??'Sunday Service'));$platform=trim((string)($_POST['live_platform']??''));$live=trim((string)($_POST['live_link']??''));$external=trim((string)($_POST['recording_url']??''));$isLive=isset($_POST['is_live'])?1:0;$status=(string)($_POST['status']??'Published');
        $recording=ce_upload('recording_file','services',['mp4','webm','mov','m4v','mp3','m4a'],300*1024*1024); $thumb=ce_upload('thumbnail','services',['jpg','jpeg','png','webp'],5*1024*1024);
        $recordingType=$recording?'upload':($external!==''?'external':null); $recordingPath=$recording?:($external?:null);
        if($id>0){
            $sets='service_title=?,service_date=?,service_time=NULLIF(?,\'\'),preacher=?,theme=?,readings=?,lessons_learnt=?,recommendations=?,service_type=?,live_platform=?,live_link=?,is_live=?,status=?';$types='sssssssssssisi';$vals=[$title,$date,$time,$preacher,$theme,$readings,$lessons,$tips,$type,$platform,$live,$isLive,$status];
            if($recordingPath){$sets.=',recording_type=?,recording_path=?';$types.='ss';$vals[]=$recordingType;$vals[]=$recordingPath;} if($thumb){$sets.=',thumbnail_path=?';$types.='s';$vals[]=$thumb;} $sets.=' WHERE id=?';$types.='i';$vals[]=$id;
            $stmt=$conn->prepare('UPDATE church_services SET '.$sets);$stmt->bind_param($types,...$vals);$stmt->execute();$stmt->close();
        }else{$uid=ce_user_id();$stmt=$conn->prepare("INSERT INTO church_services(service_title,service_date,service_time,preacher,theme,readings,lessons_learnt,recommendations,service_type,live_platform,live_link,recording_type,recording_path,thumbnail_path,is_live,status,created_by) VALUES(?,?,NULLIF(?,''),?,?,?,?,?,?,?,?,?,?,?,?,?,?)");$stmt->bind_param('ssssssssssssssisi',$title,$date,$time,$preacher,$theme,$readings,$lessons,$tips,$type,$platform,$live,$recordingType,$recordingPath,$thumb,$isLive,$status,$uid);$stmt->execute();$stmt->close();}
        ce_flash('success','Service details saved successfully.');
    } elseif($action==='save_announcement'){
        $id=(int)($_POST['id']??0);$title=trim((string)($_POST['title']??''));$message=trim((string)($_POST['message']??''));if($title===''||$message==='')throw new RuntimeException('Announcement title and message are required.');$audience=trim((string)($_POST['audience']??'All Members'));$from=str_replace('T',' ',(string)($_POST['publish_from']??date('Y-m-d H:i')));$until=str_replace('T',' ',(string)($_POST['publish_until']??''));$priority=(string)($_POST['priority']??'Normal');$status=(string)($_POST['status']??'Published');
        if($id){$stmt=$conn->prepare("UPDATE church_announcements SET title=?,message=?,audience=?,publish_from=?,publish_until=NULLIF(?,''),priority=?,status=? WHERE id=?");$stmt->bind_param('sssssssi',$title,$message,$audience,$from,$until,$priority,$status,$id);}else{$uid=ce_user_id();$stmt=$conn->prepare("INSERT INTO church_announcements(title,message,audience,publish_from,publish_until,priority,status,created_by) VALUES(?,?,?,?,NULLIF(?,''),?,?,?)");$stmt->bind_param('sssssssi',$title,$message,$audience,$from,$until,$priority,$status,$uid);} $stmt->execute();$stmt->close();ce_flash('success','Announcement saved successfully.');
    } elseif($action==='save_theme'){
        $id=(int)($_POST['id']??0);$year=(int)($_POST['theme_year']??date('Y'));$en=trim((string)($_POST['english_theme']??''));$localName=trim((string)($_POST['local_language_name']??'Local Language'));$local=trim((string)($_POST['local_theme']??''));if($en===''||$local==='')throw new RuntimeException('Both English and local-language themes are required.');$scripture=trim((string)($_POST['scripture_reference']??''));$explanation=trim((string)($_POST['explanation']??''));$active=isset($_POST['is_active'])?1:0;$uid=ce_user_id();
        $stmt=$conn->prepare("INSERT INTO church_annual_themes(id,theme_year,english_theme,local_language_name,local_theme,scripture_reference,explanation,is_active,created_by) VALUES(NULLIF(?,0),?,?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE theme_year=VALUES(theme_year),english_theme=VALUES(english_theme),local_language_name=VALUES(local_language_name),local_theme=VALUES(local_theme),scripture_reference=VALUES(scripture_reference),explanation=VALUES(explanation),is_active=VALUES(is_active)");$stmt->bind_param('iisssssii',$id,$year,$en,$localName,$local,$scripture,$explanation,$active,$uid);$stmt->execute();$stmt->close();ce_flash('success','Annual church theme saved.');
    } elseif($action==='save_harvest'){
        $id=(int)($_POST['id']??0);$year=(int)($_POST['harvest_year']??date('Y'));$name=trim((string)($_POST['harvest_name']??''));if($name==='')throw new RuntimeException('Harvest name is required.');$category=(string)($_POST['harvest_category']??'General');if(!in_array($category,['Sunday School','General'],true))$category='General';$target=(float)($_POST['target_amount']??0);$collected=(float)($_POST['amount_collected']??0);$date=(string)($_POST['harvest_date']??'');$notes=trim((string)($_POST['notes']??''));$status=(string)($_POST['status']??'Open');
        if($id){$stmt=$conn->prepare("UPDATE church_harvests SET harvest_year=?,harvest_name=?,harvest_category=?,target_amount=?,amount_collected=?,harvest_date=NULLIF(?,''),notes=?,status=? WHERE id=?");$stmt->bind_param('issddsssi',$year,$name,$category,$target,$collected,$date,$notes,$status,$id);}else{$uid=ce_user_id();$stmt=$conn->prepare("INSERT INTO church_harvests(harvest_year,harvest_name,harvest_category,target_amount,amount_collected,harvest_date,notes,status,created_by) VALUES(?,?,?,?,?,NULLIF(?,''),?,?,?)");$stmt->bind_param('issddsssi',$year,$name,$category,$target,$collected,$date,$notes,$status,$uid);} $stmt->execute();$stmt->close();ce_flash('success','Harvest record saved.');
    } elseif($action==='save_settings'){
        $enabled=isset($_POST['pledge_reminder_enabled'])?'1':'0';$day=(string)(int)($_POST['pledge_reminder_day']??0);$time=(string)($_POST['pledge_reminder_time']??'07:00');$stmt=$conn->prepare("INSERT INTO church_engagement_settings(setting_key,setting_value,updated_by) VALUES(?,?,?) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value),updated_by=VALUES(updated_by)");$uid=ce_user_id();foreach(['pledge_reminder_enabled'=>$enabled,'pledge_reminder_day'=>$day,'pledge_reminder_time'=>$time] as $k=>$v){$stmt->bind_param('ssi',$k,$v,$uid);$stmt->execute();}$stmt->close();ce_flash('success','Reminder settings saved.');
    } elseif($action==='save_pledge'){
        $id=(int)($_POST['id']??0);$mid=(int)($_POST['member_id']??0);$title=trim((string)($_POST['pledge_title']??''));if($mid<1||$title==='')throw new RuntimeException('Member and pledge title are required.');$amount=(float)($_POST['pledged_amount']??0);$paid=(float)($_POST['paid_amount']??0);$due=(string)($_POST['due_date']??'');$status=$paid>=$amount&&$amount>0?'Paid':($paid>0?'Partially Paid':'Pending');$notes=trim((string)($_POST['notes']??''));
        if($id){$stmt=$conn->prepare("UPDATE church_pledges SET member_id=?,pledge_title=?,pledged_amount=?,paid_amount=?,due_date=NULLIF(?,''),status=?,notes=? WHERE id=?");$stmt->bind_param('isddsssi',$mid,$title,$amount,$paid,$due,$status,$notes,$id);}else{$uid=ce_user_id();$stmt=$conn->prepare("INSERT INTO church_pledges(member_id,pledge_title,pledged_amount,paid_amount,due_date,status,notes,created_by) VALUES(?,?,?,?,NULLIF(?,''),?,?,?)");$stmt->bind_param('isddsssi',$mid,$title,$amount,$paid,$due,$status,$notes,$uid);} $stmt->execute();$stmt->close();ce_flash('success','Pledge saved.');
    } elseif(str_starts_with($action,'delete_')){
        $map=['delete_program'=>'church_programs','delete_service'=>'church_services','delete_announcement'=>'church_announcements','delete_theme'=>'church_annual_themes','delete_harvest'=>'church_harvests','delete_pledge'=>'church_pledges'];$table=$map[$action]??'';if($table==='')throw new RuntimeException('Invalid delete action.');$id=(int)($_POST['id']??0);$stmt=$conn->prepare("DELETE FROM `$table` WHERE id=?");$stmt->bind_param('i',$id);$stmt->execute();$stmt->close();ce_flash('success','Record deleted.');
    } else throw new RuntimeException('Invalid action.');
} catch(Throwable $e){ce_flash('danger',$e->getMessage());}
ce_redirect((string)($_POST['return_to']??'admin.php'));
